import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Card, Button, Alert, api } from '../App';

const MAX_SLOTS = 5;

const ColFilter = ({ label, options, selected, onChange }) => {
  const [open, setOpen] = useState(false);
  const [pos, setPos]   = useState({ top: 0, left: 0 });
  const triggerRef = useRef(null);
  const ref = useRef(null);

  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);

  const handleOpen = () => {
    if (triggerRef.current) {
      const r = triggerRef.current.getBoundingClientRect();
      setPos({ top: r.bottom + window.scrollY + 4, left: r.left + window.scrollX });
    }
    setOpen(o => !o);
  };

  return (
    <div ref={ref} style={{ display: 'inline-block' }}>
      <div ref={triggerRef} onClick={handleOpen}
        style={{ cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 3, userSelect: 'none' }}>
        <span style={{ fontSize: 11, fontWeight: 600 }}>{label}</span>
        {selected.length > 0
          ? <span style={{ background: '#f59e0b', color: '#fff', borderRadius: 99, fontSize: 9, padding: '1px 4px', fontWeight: 700 }}>{selected.length}</span>
          : <span style={{ fontSize: 8, opacity: 0.6 }}>&#9660;</span>}
      </div>
      {open && (
        <div style={{ position: 'absolute', top: pos.top, left: pos.left, background: '#fff', border: '1px solid #e2e8f0', borderRadius: 8, zIndex: 9999, boxShadow: '0 8px 24px rgba(0,0,0,0.18)', minWidth: 170, maxHeight: 260, overflowY: 'auto' }}>
          <div style={{ padding: '6px 10px', borderBottom: '1px solid #f0f4f8', display: 'flex', justifyContent: 'space-between', position: 'sticky', top: 0, background: '#fff' }}>
            <span style={{ fontSize: 10, color: '#888', fontWeight: 700 }}>{label}</span>
            <button onMouseDown={() => onChange([])} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 10, color: '#c0392b', fontWeight: 700 }}>Clear</button>
          </div>
          {options.map(opt => (
            <div key={opt} onMouseDown={() => onChange(selected.includes(opt) ? selected.filter(x => x !== opt) : [...selected, opt])}
              style={{ padding: '7px 10px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 7,
                background: selected.includes(opt) ? '#eff6ff' : '#fff', fontSize: 12, color: '#1a2533', borderBottom: '1px solid #f9fafb' }}>
              <div style={{ width: 13, height: 13, borderRadius: 2, flexShrink: 0,
                border: `2px solid ${selected.includes(opt) ? '#1a3c5e' : '#cbd5e0'}`,
                background: selected.includes(opt) ? '#1a3c5e' : '#fff',
                display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {selected.includes(opt) && <span style={{ color: '#fff', fontSize: 8, fontWeight: 700 }}>&#10003;</span>}
              </div>
              <span style={{ fontWeight: selected.includes(opt) ? 600 : 400 }}>{opt}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const SlotCell = ({ catalogueId, slotIdx, value, onChange, allParties, visibleLots, rowIdx }) => {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const [sugg, setSugg] = useState([]);
  const inputRef = useRef(null);
  const getSugg = v => !v ? [] : allParties.filter(p => p.party_code.startsWith(v.toUpperCase())).slice(0, 5);
  const startEdit = () => { setDraft(value?.party_code || ''); setEditing(true); setTimeout(() => { inputRef.current?.focus(); inputRef.current?.select(); }, 20); };
  const commit = useCallback((codeOverride) => {
    const c = (codeOverride ?? draft).trim().toUpperCase();
    setEditing(false); setSugg([]);
    if (!c) { onChange(null); return; }
    const p = allParties.find(x => x.party_code === c);
    onChange(p ? { party_id: p.id, party_name: p.party_name, party_code: p.party_code } : null);
  }, [draft, allParties, onChange]);
  const focusSlot = useCallback((rowI, slotI) => {
    const targetRow = visibleLots[rowI];
    if (!targetRow) return;
    const clampedSlot = Math.max(0, Math.min(MAX_SLOTS - 1, slotI));
    setTimeout(() => {
      document.querySelector(`[data-slot="${targetRow.catalogue_id}-${clampedSlot}"]`)?.click();
    }, 60);
  }, [visibleLots]);

  const handleKey = e => {
    if (e.key === 'Escape') { setEditing(false); setSugg([]); return; }
    if (e.key === 'Backspace' && draft === '') { onChange(null); setEditing(false); return; }

    // Arrow Right or Tab → next P slot (or P1 of next row)
    if (e.key === 'ArrowRight' || e.key === 'Tab') {
      e.preventDefault(); commit();
      if (slotIdx + 1 < MAX_SLOTS) focusSlot(rowIdx, slotIdx + 1);
      else focusSlot(rowIdx + 1, 0);
      return;
    }
    // Arrow Left → prev P slot (or last P of prev row)
    if (e.key === 'ArrowLeft') {
      e.preventDefault(); commit();
      if (slotIdx > 0) focusSlot(rowIdx, slotIdx - 1);
      else focusSlot(rowIdx - 1, MAX_SLOTS - 1);
      return;
    }
    // Arrow Down or Enter → same P slot, next row
    if (e.key === 'ArrowDown' || e.key === 'Enter') {
      e.preventDefault(); commit();
      focusSlot(rowIdx + 1, slotIdx);
      return;
    }
    // Arrow Up → same P slot, prev row
    if (e.key === 'ArrowUp') {
      e.preventDefault(); commit();
      focusSlot(rowIdx - 1, slotIdx);
      return;
    }
  };
  if (editing) return (
    <div style={{ position: 'relative', display: 'inline-block' }}>
      <input ref={inputRef} value={draft}
        onChange={e => { const v = e.target.value.toUpperCase(); setDraft(v); setSugg(getSugg(v)); }}
        onKeyDown={handleKey} onBlur={() => setTimeout(() => { commit(); setSugg([]); }, 160)}
        maxLength={5} style={{ width: 50, padding: '2px 4px', border: '2px solid #1a3c5e', borderRadius: 4, fontSize: 11, fontFamily: 'monospace', textTransform: 'uppercase', outline: 'none' }} />
      {sugg.length > 0 && (
        <div style={{ position: 'absolute', top: '100%', left: 0, background: '#fff', border: '1px solid #e2e8f0', borderRadius: 6, zIndex: 999, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', minWidth: 150 }}>
          {sugg.map(s => (
            <div key={s.id} onMouseDown={e => { e.preventDefault(); commit(s.party_code); }}
              style={{ padding: '5px 9px', cursor: 'pointer', fontSize: 11, borderBottom: '1px solid #f0f4f8' }}
              onMouseEnter={e => e.currentTarget.style.background = '#f0f8ff'}
              onMouseLeave={e => e.currentTarget.style.background = '#fff'}>
              <b style={{ color: '#1a3c5e' }}>{s.party_code}</b> {s.party_name}
            </div>
          ))}
        </div>
      )}
    </div>
  );
  return (
    <div data-slot={`${catalogueId}-${slotIdx}`} onClick={startEdit}
      style={{ width: 46, height: 22, padding: '1px 4px', borderRadius: 99, cursor: 'pointer',
        display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
        background: value ? '#1a3c5e' : 'transparent', border: value ? 'none' : '1.5px dashed #d1d5db' }}>
      {value ? <span style={{ color: '#fff', fontSize: 10, fontWeight: 700 }}>{value.party_code}</span>
             : <span style={{ color: '#d1d5db', fontSize: 9 }}>—</span>}
    </div>
  );
};

export default function MarkingPage() {
  const [allParties, setAllParties] = useState([]);
  const [saleNos, setSaleNos] = useState([]);
  const [selParties, setSelParties] = useState([]);
  const [saleNo, setSaleNo] = useState('');
  const [partySearch, setPartySearch] = useState('');
  const [allLots, setAllLots] = useState([]);
  const [lotSlots, setLotSlots] = useState({});
  const [loading, setLoading] = useState(false);
  const [marking, setMarking] = useState(false);
  const [saving, setSaving] = useState(false);
  const [alert, setAlert] = useState(null);
  const [dupAlerts, setDupAlerts] = useState({});
  const [filterGrades, setFilterGrades] = useState([]);
  const [filterGpDates, setFilterGpDates] = useState([]);
  const [filterGardens, setFilterGardens] = useState([]);
  const [filterBrokers, setFilterBrokers] = useState([]);
  const [searchLot, setSearchLot] = useState('');
  const [showMarked, setShowMarked] = useState(false);
  const [visibleCount, setVisibleCount] = useState(200);
  const [skipBGG, setSkipBGG] = useState(false); // Skip when Broker+Garden+Grade same
  const [aiParties, setAiParties] = useState([]);  // multi-select
  const [aiSaleNos, setAiSaleNos] = useState([]);   // multi-select sale nos
  const [aiSugg, setAiSugg] = useState([]);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiApplying, setAiApplying] = useState(false);
  const [saveAsAi, setSaveAsAi] = useState(false);  // save with is_ai_suggestion flag

  useEffect(() => {
    Promise.all([api.get('/parties').catch(() => ({ data: [] })), api.get('/import/sale-numbers').catch(() => ({ data: [] }))])
      .then(([p, s]) => { setAllParties(p.data); setSaleNos(s.data); });
  }, []);

  const loadSale = useCallback(async (sale) => {
    if (!sale) return;
    setLoading(true); setAiSugg([]);
    setFilterGrades([]); setFilterGardens([]); setFilterBrokers([]); setSearchLot('');
    setShowMarked(false); setVisibleCount(200); setSelParties([]);
    try {
      const [lotsRes, slotsRes] = await Promise.all([
        api.post('/marking/preview', { party_ids: [], sale_no: sale }),
        api.get(`/marking/saved-slots?sale_no=${sale}`)
      ]);
      const lots = lotsRes.data.lots || [];
      setAllLots(lots);
      const initSlots = {};
      lots.forEach(l => { initSlots[l.catalogue_id] = Array(MAX_SLOTS).fill(null); });
      const saved = slotsRes.data || {};
      Object.entries(saved).forEach(([cid, parties]) => {
        if (initSlots[cid]) parties.forEach((p, i) => { if (i < MAX_SLOTS) initSlots[cid][i] = p; });
      });
      setLotSlots(initSlots);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setLoading(false); }
  }, []);

  const handleSaleChange = s => { setSaleNo(s); if (s) loadSale(s); };

  const markLots = async () => {
    if (!selParties.length || !saleNo) { setAlert({ msg: 'Select parties first', type: 'error' }); return; }
    setMarking(true); setAlert(null);
    try {
      const r = await api.post('/marking/preview', { party_ids: selParties.map(p => p.id), sale_no: saleNo, skip_bgg: skipBGG });
      const lots = r.data.lots || [];
      const parties = r.data.parties || [];
      // Build a map of party_id -> skip_bgg flag from party master settings
      const partySkipBGG = new Map(parties.map(p => [p.party_id, p.skip_bgg || false]));

      setLotSlots(prev => {
        const next = { ...prev };
        // Track BGG (Broker+Garden+Grade) per party — only enforced if party has skip_bgg enabled
        const partyBGGSeen = new Map();

        lots.forEach(lot => {
          const eligible = lot.party_slots_array || [];
          if (!eligible.length) return;
          const existing = [...(next[lot.catalogue_id] || Array(MAX_SLOTS).fill(null))];
          const existingIds = new Set(existing.filter(Boolean).map(s => s.party_id));

          for (const ep of eligible) {
            // Skip if already in this lot's slots
            if (existingIds.has(ep.party_id)) continue;

            // BGG dedup — only if this party has the flag enabled in their party master
            if (partySkipBGG.get(ep.party_id)) {
              const bggKey = `${lot.broker}__${lot.garden}__${lot.grade}`;
              if (!partyBGGSeen.has(ep.party_id)) partyBGGSeen.set(ep.party_id, new Set());
              const seen = partyBGGSeen.get(ep.party_id);
              if (seen.has(bggKey)) continue; // already took first lot for this BGG
              seen.add(bggKey);
            }

            const emptyIdx = existing.findIndex(s => !s);
            if (emptyIdx >= 0) {
              existing[emptyIdx] = ep;
              existingIds.add(ep.party_id);
            }
          }
          next[lot.catalogue_id] = existing;
        });
        return next;
      });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setMarking(false); }
  };

  const updateSlot = (catalogueId, slotIdx, value) => {
    setLotSlots(prev => {
      const arr = [...(prev[catalogueId] || Array(MAX_SLOTS).fill(null))];
      arr[slotIdx] = value;
      return { ...prev, [catalogueId]: arr };
    });
    if (value?.party_id && saleNo) {
      const lot = allLots.find(l => l.catalogue_id === catalogueId);
      if (lot) {
        api.post('/marking/check-duplicate', { party_id: value.party_id, sale_no: saleNo, garden: lot.garden, grade: lot.grade, broker: lot.broker })
          .then(r => {
            if (r.data.exists) {
              const lotNos = r.data.lot_nos || lot.lot_no || '?';
              setDupAlerts(prev => ({ ...prev, [catalogueId]: `\u26A0\uFE0F ${value.party_code} already marked for ${lot.garden}/${lot.grade} — Lots: ${lotNos}. Duplicate allowed.` }));
              setTimeout(() => setDupAlerts(prev => { const n = {...prev}; delete n[catalogueId]; return n; }), 8000);
            }
          }).catch(() => {});
      }
    }
  };

  const save = async () => {
    const allMarkedLots = allLots.filter(l => (lotSlots[l.catalogue_id] || []).some(s => s?.party_id))
      .map(l => ({ ...l, party_slots_array: (lotSlots[l.catalogue_id] || []).filter(Boolean), final_slots: (lotSlots[l.catalogue_id] || []).filter(Boolean), final_price: l.suggested_price }));
    if (!allMarkedLots.length) { setAlert({ msg: 'No markings to save', type: 'warning' }); return; }
    // Deduplicate: one entry per unique party+garden+grade combo
    // Multiple lots of same garden+grade should only produce ONE marking record
    const seen = new Set();
    const markedLots = allMarkedLots.filter(m => {
      const slots = (m.final_slots || []).filter(Boolean);
      const keys = slots.map(p => `${p.party_id}__${m.garden}__${m.grade}`);
      const isNew = keys.some(k => !seen.has(k));
      keys.forEach(k => seen.add(k));
      return isNew;
    });
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings: markedLots, sale_no: saleNo, is_ai_suggestion: saveAsAi });
      setAlert({ msg: `\u2705 ${r.data.saved} new markings saved. ${r.data.skipped} already existed (kept intact).`, type: 'success' });
      const slotsRes = await api.get(`/marking/saved-slots?sale_no=${saleNo}`);
      const saved = slotsRes.data || {};
      setLotSlots(prev => {
        const next = { ...prev };
        Object.entries(saved).forEach(([cid, parties]) => {
          if (!next[cid]) next[cid] = Array(MAX_SLOTS).fill(null);
          parties.forEach((p, i) => { if (i < MAX_SLOTS) next[cid][i] = p; });
        });
        return next;
      });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setSaving(false); }
  };

  const loadAiSugg = async () => {
    if (!aiParties.length || !aiSaleNos.length) return;
    setAiLoading(true);
    try {
      const r = await api.post('/marking/ai-suggest', {
        party_ids: aiParties,
        sale_nos: aiSaleNos,
        current_sale_no: saleNo || undefined
      });
      setAiSugg(r.data.suggestions || []);
    } catch (e) { console.error(e); }
    finally { setAiLoading(false); }
  };

  const applyAiSugg = async () => {
    if (!aiParties.length || !saleNo || !aiSugg.length) return;
    setAiApplying(true);
    try {
      // Apply per-party grouped suggestions
      const byParty = {};
      aiSugg.forEach(s => { if (!byParty[s.party_id]) byParty[s.party_id] = []; byParty[s.party_id].push(s); });
      let totalApplied = 0, totalNotFound = 0;
      for (const [pid, suggs] of Object.entries(byParty)) {
        const r = await api.post('/marking/apply-ai', { party_id: pid, sale_no: saleNo, suggestions: suggs });
        totalApplied += r.data.applied || 0; totalNotFound += r.data.notFound || 0;
      }
      setAlert({ msg: `\u2705 AI: ${totalApplied} markings applied. ${totalNotFound} not found in current sale.`, type: 'success' });
      const slotsRes = await api.get(`/marking/saved-slots?sale_no=${saleNo}`);
      const saved = slotsRes.data || {};
      setLotSlots(prev => {
        const next = { ...prev };
        Object.entries(saved).forEach(([cid, parties]) => {
          if (!next[cid]) next[cid] = Array(MAX_SLOTS).fill(null);
          parties.forEach((p, i) => { if (i < MAX_SLOTS) next[cid][i] = p; });
        });
        return next;
      });
      setAiSugg([]);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setAiApplying(false); }
  };

  const clearAllMarkings = async () => {
    if (!saleNo) return;
    if (!window.confirm(`Clear ALL saved markings for Sale #${saleNo}? This cannot be undone.`)) return;
    try {
      const r = await api.delete(`/marking/clear-all?sale_no=${saleNo}`);
      setAlert({ msg: `✅ All ${r.data.deleted} markings cleared for Sale #${saleNo}. Starting fresh.`, type: 'success' });
      setLotSlots(prev => {
        const next = {};
        Object.keys(prev).forEach(k => { next[k] = Array(MAX_SLOTS).fill(null); });
        return next;
      });
    } catch (e) { setAlert({ msg: 'Failed to clear markings: ' + (e.response?.data?.error || e.message), type: 'error' }); }
  };
  const fmtDate = d => { try { const dt = new Date(d); return `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}`; } catch { return '—'; } };
  const toggleParty = p => setSelParties(prev => prev.find(x => x.id === p.id) ? prev.filter(x => x.id !== p.id) : [...prev, { id: p.id, party_name: p.party_name, party_code: p.party_code }]);
  const filteredParties = allParties.filter(p => p.party_name.toLowerCase().includes(partySearch.toLowerCase()) || p.party_code.toLowerCase().includes(partySearch.toLowerCase()));
  const gradesOpts  = [...new Set(allLots.map(r => r.grade).filter(Boolean))].sort();
  const gpDateOpts = [...new Set(allLots.map(r => fmtDate(r.gp_date)).filter(Boolean))].sort();
  const gardensOpts = [...new Set(allLots.map(r => r.garden).filter(Boolean))].sort();
  const brokersOpts = [...new Set(allLots.map(r => r.broker).filter(Boolean))].sort();
  const markedCount = allLots.filter(l => (lotSlots[l.catalogue_id] || []).some(s => s?.party_id)).length;

  const filteredLots = allLots.filter(row => {
    if (filterGrades.length  > 0 && !filterGrades.includes(row.grade))   return false;
    if (filterGardens.length > 0 && !filterGardens.includes(row.garden)) return false;
    if (filterBrokers.length > 0 && !filterBrokers.includes(row.broker)) return false;
    if (searchLot && !(row.lot_no || '').toLowerCase().includes(searchLot.toLowerCase())) return false;
    if (showMarked && !(lotSlots[row.catalogue_id] || []).some(s => s?.party_id)) return false;
    if (filterGpDates.length > 0 && !filterGpDates.includes(fmtDate(row.gp_date))) return false;
    return true;
  });

  const visibleLots = filteredLots.slice(0, visibleCount);
  const hasMore = filteredLots.length > visibleCount;
  const hasFilters = filterGrades.length > 0 || filterGardens.length > 0 || filterBrokers.length > 0 || searchLot || showMarked;
  const clearFilters = () => { setFilterGrades([]); setFilterGardens([]); setFilterBrokers([]); setSearchLot(''); setShowMarked(false); setFilterGpDates([]); setVisibleCount(200); };

  const fmtRate = row => {
    const mn = row.min_deal_price, mx = row.max_deal_price;
    if (!mn && !mx) return '—';
    if (mn && mx && Math.abs(parseFloat(mn) - parseFloat(mx)) > 0.5) return `${Number(mn).toFixed(0)}-${Number(mx).toFixed(0)}`;
    return `${Number(mn || mx).toFixed(0)}/-`;
  };
  const td = (extra = {}) => ({ padding: '4px 6px', fontSize: 12, color: '#374151', fontWeight: 500, ...extra });

  return (
    <div>
      <h2 style={{ marginBottom: 2, color: '#1a3c5e', fontSize: 20, fontWeight: 800 }}>Create Markings</h2>
      <p style={{ color: '#9ca3af', fontSize: 12, marginBottom: 14 }}>Select sale to load lots. Pick parties, click Mark Lots. Click any P slot — use Arrow keys to navigate, Enter/↓ to move down.</p>
      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <Card style={{ marginBottom: 14, padding: 14 }}>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap', marginBottom: 14 }}>
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 3, textTransform: 'uppercase', letterSpacing: 0.5 }}>Sale Number *</label>
            <select value={saleNo} onChange={e => handleSaleChange(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
              <option value="">Select sale to load lots...</option>
              {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
            </select>
          </div>
          {allLots.length > 0 && (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
              <span style={{ fontSize: 12, color: '#6b7280' }}><b style={{ color: '#1a2533' }}>{allLots.length}</b> lots &middot; <b style={{ color: '#1a7a4a' }}>{filteredLots.length}</b> shown &middot; <b style={{ color: '#1a7a4a' }}>{markedCount}</b> marked</span>
              <button onClick={() => setShowMarked(v => !v)}
                style={{ padding: '4px 10px', borderRadius: 5, cursor: 'pointer', fontSize: 11, fontWeight: 600, background: showMarked ? '#1a7a4a' : '#f0fdf4', color: showMarked ? '#fff' : '#1a7a4a', border: `1.5px solid ${showMarked ? '#1a7a4a' : '#bbf7d0'}` }}>
                {showMarked ? 'Marked Only' : 'Show Marked'}
              </button>
              {hasFilters && <button onClick={clearFilters} style={{ padding: '4px 10px', borderRadius: 5, fontSize: 11, color: '#c0392b', background: 'none', border: '1px solid #fecaca', cursor: 'pointer' }}>Clear filters</button>}
              {markedCount > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                  <Button onClick={save} disabled={saving} variant="success" style={{ padding: '6px 16px', fontSize: 12 }}>
                    {saving ? 'Saving...' : `Save ${markedCount} Markings`}
                  </Button>
                  <label style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 10, cursor: 'pointer', color: saveAsAi ? '#1a7a4a' : '#888' }}>
                    <input type="checkbox" checked={saveAsAi} onChange={e => setSaveAsAi(e.target.checked)} style={{ width: 12, height: 12 }} />
                    Save as AI Reference
                  </label>
                </div>
              )}
              {saleNo && (
                <button onClick={clearAllMarkings}
                  style={{ padding: '4px 10px', borderRadius: 5, fontSize: 11, color: '#991b1b', background: '#fee2e2', border: '1px solid #fecaca', cursor: 'pointer', fontWeight: 600 }}
                  title="Delete all saved markings for this sale and start fresh">
                  🗑 Clear All Markings
                </button>
              )}
            </div>
          )}
        </div>

        {allLots.length > 0 && (
          <>
            <div style={{ fontSize: 10, fontWeight: 700, color: '#6b7280', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 6 }}>Select Parties then click Mark Lots</div>
            <div style={{ display: 'flex', gap: 6, marginBottom: 7, alignItems: 'center' }}>
              <input value={partySearch} onChange={e => setPartySearch(e.target.value)} placeholder="Search parties..."
                style={{ padding: '5px 8px', border: '1.5px solid #e2e8f0', borderRadius: 5, fontSize: 12, width: 160 }} />
              <button onClick={() => setSelParties(filteredParties.map(p => ({ id: p.id, party_name: p.party_name, party_code: p.party_code })))} style={{ padding: '5px 10px', borderRadius: 5, border: '1.5px solid #1a3c5e', background: '#1a3c5e', color: '#fff', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>Select All</button>
              <button onClick={() => setSelParties([])} style={{ padding: '5px 10px', borderRadius: 5, border: '1.5px solid #e2e8f0', background: '#f9fafb', color: '#555', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}>Deselect All</button>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, maxHeight: 110, overflowY: 'auto', marginBottom: 10 }}>
              {filteredParties.map(p => {
                const sel = !!selParties.find(x => x.id === p.id);
                const idx = selParties.findIndex(x => x.id === p.id);
                return (
                  <div key={p.id} onClick={() => toggleParty(p)}
                    style={{ padding: '4px 10px', borderRadius: 18, cursor: 'pointer', fontSize: 11, fontWeight: 600, userSelect: 'none',
                      background: sel ? '#1a3c5e' : '#f0f4f8', color: sel ? '#fff' : '#555',
                      border: `1.5px solid ${sel ? '#1a3c5e' : '#e2e8f0'}`, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                    {sel && <span style={{ background: 'rgba(255,255,255,0.2)', borderRadius: 99, padding: '0 4px', fontSize: 9 }}>P{idx+1}</span>}
                    [{p.party_code}] {p.party_name}
                  </div>
                );
              })}
            </div>
            {selParties.length > 0 && (
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 12 }}>
                <Button onClick={markLots} disabled={marking} variant="primary" style={{ padding: '6px 16px', fontSize: 12 }}>{marking ? 'Marking...' : 'Mark Lots'}</Button>
                <button onClick={() => setSelParties([])} style={{ padding: '5px 10px', borderRadius: 5, border: '1.5px solid #e2e8f0', background: '#f9fafb', color: '#555', fontSize: 11, cursor: 'pointer' }}>Clear</button>
                {/* Skip BGG toggle */}
                <label style={{ display: 'flex', alignItems: 'center', gap: 6, cursor: 'pointer', fontSize: 11, color: skipBGG ? '#1a7a4a' : '#555',
                  padding: '4px 10px', borderRadius: 5, border: `1.5px solid ${skipBGG ? '#1a7a4a' : '#e2e8f0'}`,
                  background: skipBGG ? '#f0fdf4' : '#f9fafb', userSelect: 'none' }}>
                  <input type="checkbox" checked={skipBGG} onChange={e => setSkipBGG(e.target.checked)} style={{ width: 13, height: 13 }} />
                  Skip dup Broker+Garden+Grade
                </label>
                <span style={{ fontSize: 11, color: '#888' }}>{selParties.length} selected: {selParties.map((p,i) => `P${i+1}:${p.party_code}`).join(' | ')}</span>
              </div>
            )}

            <div style={{ padding: '10px 14px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: '#92400e', marginBottom: 8 }}>
                💡 AI Marking Suggestions
                <span style={{ fontSize: 10, fontWeight: 400, marginLeft: 8, color: '#b45309' }}>Based on past markings saved as AI Reference</span>
              </div>
              {/* Party multi-select for AI */}
              <div style={{ marginBottom: 8 }}>
                <div style={{ fontSize: 10, fontWeight: 700, color: '#92400e', marginBottom: 4, textTransform: 'uppercase', display: 'flex', alignItems: 'center', gap: 8 }}>
                Select Parties for suggestion
                <button onMouseDown={() => setAiParties(allParties.map(p => p.id))}
                  style={{ padding: '1px 8px', borderRadius: 4, border: '1px solid #f59e0b', background: '#fef3c7', color: '#92400e', fontSize: 9, fontWeight: 700, cursor: 'pointer' }}>
                  Select All
                </button>
                <button onMouseDown={() => setAiParties([])}
                  style={{ padding: '1px 8px', borderRadius: 4, border: '1px solid #fde68a', background: '#fffbeb', color: '#92400e', fontSize: 9, fontWeight: 700, cursor: 'pointer' }}>
                  Clear
                </button>
              </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, maxHeight: 80, overflowY: 'auto', padding: '3px 0' }}>
                  {allParties.map(p => {
                    const sel = aiParties.includes(p.id);
                    return (
                      <div key={p.id} onClick={() => setAiParties(prev => sel ? prev.filter(x => x !== p.id) : [...prev, p.id])}
                        style={{ padding: '3px 8px', borderRadius: 14, cursor: 'pointer', fontSize: 11, fontWeight: 600, userSelect: 'none',
                          background: sel ? '#f59e0b' : '#fef3c7', color: sel ? '#fff' : '#92400e',
                          border: `1.5px solid ${sel ? '#f59e0b' : '#fde68a'}` }}>
                        {sel ? '✓ ' : ''}[{p.party_code}] {p.party_name}
                      </div>
                    );
                  })}
                </div>
                {aiParties.length > 0 && <div style={{ fontSize: 10, color: '#92400e', marginTop: 3 }}>{aiParties.length} party(s) selected</div>}
              </div>
              {/* Sale nos multi-select for AI */}
              <div style={{ marginBottom: 8 }}>
                <div style={{ fontSize: 10, fontWeight: 700, color: '#92400e', marginBottom: 4, textTransform: 'uppercase' }}>Select Reference Sale Numbers</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5 }}>
                  {saleNos.map(s => {
                    const sel = aiSaleNos.includes(String(s.sale_no));
                    return (
                      <div key={s.sale_no} onClick={() => setAiSaleNos(prev => sel ? prev.filter(x => x !== String(s.sale_no)) : [...prev, String(s.sale_no)])}
                        style={{ padding: '3px 10px', borderRadius: 14, cursor: 'pointer', fontSize: 11, fontWeight: 700, userSelect: 'none',
                          background: sel ? '#f59e0b' : '#fef3c7', color: sel ? '#fff' : '#92400e',
                          border: `1.5px solid ${sel ? '#f59e0b' : '#fde68a'}` }}>
                        {sel ? '✓ ' : ''}Sale {s.sale_no}
                      </div>
                    );
                  })}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 7, alignItems: 'center', flexWrap: 'wrap' }}>
                <button onClick={loadAiSugg} disabled={aiLoading || !aiParties.length || !aiSaleNos.length}
                  style={{ padding: '5px 12px', background: '#f59e0b', color: '#fff', border: 'none', borderRadius: 5, cursor: 'pointer', fontWeight: 700, fontSize: 12 }}>
                  {aiLoading ? 'Loading...' : 'Get Suggestions'}
                </button>
                {aiSugg.length > 0 && <>
                  <button onClick={applyAiSugg} disabled={aiApplying || !saleNo}
                    style={{ padding: '5px 12px', background: '#1a7a4a', color: '#fff', border: 'none', borderRadius: 5, cursor: 'pointer', fontWeight: 700, fontSize: 12 }}>
                    {aiApplying ? 'Applying...' : `Apply ${aiSugg.length} to Sale #${saleNo}`}
                  </button>
                  <button onClick={() => setAiSugg([])} style={{ fontSize: 11, background: 'none', border: 'none', cursor: 'pointer', color: '#888' }}>Clear</button>
                </>}
              </div>
              {aiSugg.length > 0 && (
                <div style={{ overflowX: 'auto', marginTop: 10 }}>
                  <table style={{ fontSize: 11, borderCollapse: 'collapse', width: '100%' }}>
                    <thead><tr style={{ background: '#fef3c7' }}>
                      {['Party','Garden','Grade','×','Range','Confidence'].map(h => <th key={h} style={{ padding: '4px 8px', textAlign: 'left', fontWeight: 700, color: '#92400e' }}>{h}</th>)}
                    </tr></thead>
                    <tbody>{aiSugg.map((s, i) => (
                      <tr key={i} style={{ borderBottom: '1px solid #fde68a', background: i%2===0?'#fffbeb':'#fef9e7' }}>
                        <td style={{ padding: '4px 8px' }}><span style={{ background: '#1a3c5e', color: '#fff', padding: '1px 6px', borderRadius: 99, fontSize: 10, fontWeight: 700 }}>{s.party_code}</span></td>
                        <td style={{ padding: '4px 8px', fontWeight: 700, color: '#1a3c5e', fontSize: 11 }}>{s.garden}</td>
                        <td style={{ padding: '4px 8px' }}><span style={{ background: '#dbeafe', color: '#1e40af', padding: '1px 6px', borderRadius: 99, fontSize: 10, fontWeight: 700 }}>{s.grade}</span></td>
                        <td style={{ padding: '4px 8px', fontWeight: 700, fontSize: 11 }}>{s.frequency}</td>
                        <td style={{ padding: '4px 8px', fontSize: 11 }}>{s.price_range}</td>
                        <td style={{ padding: '4px 8px' }}><span style={{ padding: '1px 7px', borderRadius: 99, fontSize: 10, fontWeight: 700, background: s.confidence==='High'?'#dcfce7':s.confidence==='Medium'?'#fef9c3':'#fee2e2', color: s.confidence==='High'?'#166534':s.confidence==='Medium'?'#92400e':'#991b1b' }}>{s.confidence}</span></td>
                      </tr>
                    ))}</tbody>
                  </table>
                </div>
              )}
            </div>
          </>
        )}
      </Card>

      {allLots.length > 0 && (
        <Card style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '8px 14px', background: '#1a3c5e', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>All Lots - Sale #{saleNo}{hasFilters && <span style={{ fontSize: 10, fontWeight: 400, marginLeft: 8, opacity: 0.8 }}>({filteredLots.length} of {allLots.length})</span>}</div>
            <div style={{ fontSize: 10, opacity: 0.7 }}>Click slot | →/Tab=right | ←=left | ↓/Enter=down | ↑=up | Backspace=clear</div>
          </div>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#234d78', color: '#fff' }}>
                  <th style={{ padding: '7px 6px', textAlign: 'center', fontSize: 11, minWidth: 50 }}>Sale</th>
                  {[1,2,3,4,5].map(n => <th key={n} style={{ padding: '7px 4px', textAlign: 'center', background: '#1a3c5e', width: 54, fontSize: 11 }}>P{n}</th>)}
                  <th style={{ padding: '7px 6px', textAlign: 'left', fontSize: 11 }}><ColFilter label="Bro" options={brokersOpts} selected={filterBrokers} onChange={setFilterBrokers} /></th>
                  <th style={{ padding: '7px 6px', textAlign: 'left', fontSize: 11 }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                      <span style={{ fontWeight: 600 }}>Lot</span>
                      <input value={searchLot} onChange={e => setSearchLot(e.target.value)} onClick={e => e.stopPropagation()} placeholder="Search..."
                        style={{ width: 58, padding: '1px 4px', border: '1px solid rgba(255,255,255,0.3)', borderRadius: 3, fontSize: 9, background: 'rgba(255,255,255,0.15)', color: '#fff', outline: 'none' }} />
                    </div>
                  </th>
                  <th style={{ padding: '7px 6px', textAlign: 'left', minWidth: 95, fontSize: 11 }}><ColFilter label="Garden" options={gardensOpts} selected={filterGardens} onChange={setFilterGardens} /></th>
                  <th style={{ padding: '7px 6px', textAlign: 'left', fontSize: 11 }}><ColFilter label="Grd" options={gradesOpts} selected={filterGrades} onChange={setFilterGrades} /></th>
                  <th style={{ padding: '7px 6px', textAlign: 'right', fontSize: 11, minWidth: 80 }}>Rate</th>
                  <th style={{ padding: '7px 6px', textAlign: 'left', fontSize: 11, minWidth: 85 }}>Origin</th>
                  <th style={{ padding: '7px 6px', textAlign: 'right', fontSize: 11 }}>Qty</th>
                  <th style={{ padding: '7px 6px', textAlign: 'right', fontSize: 11 }}>NWt</th>
                  <th style={{ padding: '7px 6px', textAlign: 'center', fontSize: 11 }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                      <span style={{ fontWeight: 600 }}>GP Dt</span>
                      <ColFilter label="" options={gpDateOpts} selected={filterGpDates} onChange={setFilterGpDates} />
                    </div>
                  </th>
                  <th style={{ padding: '7px 6px', textAlign: 'left', fontSize: 11 }}>Invoice</th>
                </tr>
              </thead>
              <tbody>
                {visibleLots.length === 0
                  ? <tr><td colSpan={14} style={{ padding: 20, textAlign: 'center', color: '#aaa' }}>No lots match filters. <button onClick={clearFilters} style={{ color: '#1a3c5e', background: 'none', border: 'none', cursor: 'pointer', textDecoration: 'underline' }}>Clear</button></td></tr>
                  : visibleLots.map((row, rowIdx) => {
                    const slots = lotSlots[row.catalogue_id] || Array(MAX_SLOTS).fill(null);
                    const hasSlot = slots.some(s => s?.party_id);
                    const dup = dupAlerts[row.catalogue_id];
                    return (
                      <React.Fragment key={row.catalogue_id}>
                        <tr style={{ borderBottom: dup ? 'none' : '1px solid #f0f4f8', background: hasSlot ? (rowIdx%2===0?'#f0fdf4':'#e8faf0') : (rowIdx%2===0?'#fff':'#fafbfc') }}>
                          <td style={td({ textAlign: 'center', color: '#9ca3af', fontWeight: 500 })}>{row.sale_no}</td>
                          {slots.map((slot, si) => (
                            <td key={si} style={{ padding: '3px 2px', textAlign: 'center' }}>
                              <SlotCell catalogueId={row.catalogue_id} slotIdx={si} value={slot} onChange={v => updateSlot(row.catalogue_id, si, v)} allParties={allParties} visibleLots={visibleLots} rowIdx={rowIdx} />
                            </td>
                          ))}
                          <td style={td({ fontWeight: 600 })}>{row.broker}</td>
                          <td style={td({ fontFamily: 'monospace', color: '#1a3c5e', fontWeight: 700 })}>{row.lot_no}</td>
                          <td style={{ ...td({ fontWeight: 700, color: '#1a3c5e' }), maxWidth: 105, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={row.garden}>{row.garden}</td>
                          <td style={td()}><span style={{ background: '#dbeafe', color: '#1e40af', padding: '1px 6px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span></td>
                          <td style={td({ textAlign: 'right', fontWeight: 700, color: '#1a3c5e', fontSize: 12 })}>{fmtRate(row)}</td>
                          <td style={{ ...td({ color: '#6b7280', fontSize: 11 }), maxWidth: 85, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={row.origin}>{row.origin || '—'}</td>
                          <td style={td({ textAlign: 'right', fontWeight: 700 })}>{row.bags || '—'}</td>
                          <td style={td({ textAlign: 'right', fontWeight: 700 })}>{row.net_wt || '—'}</td>
                          <td style={td({ textAlign: 'center', color: '#374151', fontWeight: 600 })}>{fmtDate(row.gp_date)}</td>
                          <td style={td({ color: '#374151', fontFamily: 'monospace', fontSize: 12, fontWeight: 600 })}>{row.invoice || '—'}</td>
                        </tr>
                        {dup && (
                          <tr><td colSpan={14} style={{ padding: '3px 12px', background: '#fffbeb', borderBottom: '1px solid #f0f4f8', fontSize: 11, color: '#92400e', fontWeight: 600 }}>
                            {dup}
                            <button onClick={() => setDupAlerts(prev => { const n={...prev}; delete n[row.catalogue_id]; return n; })} style={{ marginLeft: 8, border: 'none', background: 'none', cursor: 'pointer', fontSize: 10, color: '#888' }}>x</button>
                          </td></tr>
                        )}
                      </React.Fragment>
                    );
                  })
                }
              </tbody>
            </table>
          </div>
          {hasMore && (
            <div style={{ padding: '10px', textAlign: 'center', borderTop: '1px solid #f0f4f8', background: '#fafbfc' }}>
              <span style={{ fontSize: 12, color: '#6b7280', marginRight: 10 }}>Showing {Math.min(visibleCount, filteredLots.length)} of {filteredLots.length}</span>
              <button onClick={() => setVisibleCount(v => v + 200)} style={{ padding: '5px 12px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 5, cursor: 'pointer', fontSize: 12, fontWeight: 600, marginRight: 6 }}>Load 200 more</button>
              <button onClick={() => setVisibleCount(filteredLots.length)} style={{ padding: '5px 12px', background: '#f0f4f8', color: '#1a3c5e', border: '1.5px solid #1a3c5e', borderRadius: 5, cursor: 'pointer', fontSize: 12, fontWeight: 600 }}>Load All ({filteredLots.length})</button>
            </div>
          )}
        </Card>
      )}
      {!saleNo && <Card style={{ textAlign: 'center', padding: 40, color: '#aaa' }}>Select a Sale Number above to load all catalogue lots</Card>}
      {saleNo && loading && <Card style={{ textAlign: 'center', padding: 40, color: '#888' }}>Loading lots...</Card>}
    </div>
  );
}
